local u=workspace:FindFirstChild("SF_Update",true) assert(u,"SF_Update not found") local RS=game:GetService("ReplicatedStorage") local SSS=game:GetService("ServerScriptService") local SPS=game:GetService("StarterPlayer").StarterPlayerScripts local function swap(from,to) for _,c in ipairs(from:GetChildren()) do local o=to:FindFirstChild(c.Name) if o then o:Destroy() end c.Parent=to end end local old=RS:FindFirstChild("Shared") if old then old:Destroy() end u.Shared.Parent=RS swap(u.Server,SSS) swap(u.Client,SPS) u:Destroy() workspace.StreamingEnabled=false pcall(function() game.Lighting.Technology=Enum.Technology.Future end) game.Lighting.EnvironmentDiffuseScale=1 game.Lighting.EnvironmentSpecularScale=0.6 local cfg=require(RS.Shared.Config) print("SF_UPDATE OK build",cfg.Build,"DevTools",cfg.DevTools,"crate",cfg.Monetization.CrateProductId,"server",#SSS:GetChildren(),"client",#SPS:GetChildren())
